import{_ as e,o as s,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Crimson/Seastar OSD Meeting 2019-01-01","description":"","frontmatter":{"title":"Crimson/Seastar OSD Meeting 2019-01-01","date":"2019-01-01T00:00:00.000Z","updated":"2019-01-04T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","bluestore","bluefs","rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","消息传递机制","数据结构","性能分析","segment fault","system allocator","ninja命令","GDB PMP","wall clock"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-01.md","filePath":"posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-01.md","lastUpdated":1780460162000}'),l={name:"posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-01.md"};function i(n,t,a,_,p,g){return s(),o("div",null,[...t[0]||(t[0]=[r("<p>在2019年1月1日的Ceph分布式存储系统开发与性能分析会议上，多位Ceph研发人员和字幕翻译人员参与了讨论。以下是会议的主要内容：</p><p><strong>会议内容</strong>：</p><ul><li><strong>Monitor客户端改进</strong>： 讨论了Monitor客户端的改进，包括对monitor play到monitor client的更改，以及对对象分配和引用计数问题的关注。</li><li><strong>消息传递机制</strong>： 讨论了消息传递机制（如message F）的问题，包括如何确保对象在远程端不会被修改，以及可能需要扩展消息引用定义的需求。</li><li><strong>数据结构破坏</strong>： 讨论了数据结构破坏的问题，如何确保对象在释放前被正确销毁，以及使用system allocator避免段错误的可能性。</li><li><strong>代码贡献与审查</strong>： 讨论了代码贡献和审查流程，如何将代码提交到上游，以及使用ninja命令进行构建时遇到的问题。</li><li><strong>性能分析</strong>： 分享了性能分析的经验，包括使用GDB PMP和wall clock工具进行性能分析，并讨论了消息传递机制（如sister和messenger）的性能差异。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续改进Monitor客户端。</li><li>解决消息传递机制中存在的问题。</li><li>分析数据结构破坏的原因，并修复相关代码。</li><li>完成代码贡献和审查流程。</li><li>继续进行性能分析，并优化Ceph的性能。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了多个pull request（PR）和相关链接，但未在纪要中列出。</li><li>会议中讨论了一些具体的技术细节，但未在纪要中详细说明。</li></ul><p>此总结准确反映了原始内容的要点，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p>",8)])])}const S=e(l,[["render",i]]);export{m as __pageData,S as default};
